import{_ as r,o as s,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const c=JSON.parse('{"title":"トラブルシューティング","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/troubleshooting.md","filePath":"ja-JP/user-guide/troubleshooting.md","lastUpdated":1787586465000}'),a={name:"ja-JP/user-guide/troubleshooting.md"};function n(i,t,l,g,h,d){return s(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="トラブルシューティング" tabindex="-1">トラブルシューティング <a class="header-anchor" href="#トラブルシューティング" aria-label="Permalink to &quot;トラブルシューティング&quot;">​</a></h1><p>Lertaro の使用中に問題が発生した場合は、以下の手順に従って原因を確認・解決してください。</p><h2 id="_1-グローバルホットキーが反応しない" tabindex="-1">1. グローバルホットキーが反応しない <a class="header-anchor" href="#_1-グローバルホットキーが反応しない" aria-label="Permalink to &quot;1. グローバルホットキーが反応しない&quot;">​</a></h2><ul><li><strong>バックグラウンドサービスの状態確認</strong>：<a href="./settings/service-status.html"><strong>設定 → サービス状態</strong></a> を開き、<code>Lertaro.Service</code> が「実行中」であることを確認してください。通常のホットキーは App が処理しますが、昇格フックの常駐はサービスに依存しています。</li><li><strong>管理者権限の分離（UIPI）</strong>：フォアグラウンドのアプリが管理者権限で実行されている場合（例: 管理者コマンドプロンプトやタスクマネージャー）、Windows のセキュリティ機能（UIPI）により低権限プロセスからのキー入力がブロックされます。Lertaro はサービス経由でフックを自動昇格させますので、サービスが実行中であることを確認してください。</li><li><strong>プロセスブラックリストの確認</strong>：<a href="./settings/hotkeys-page.html#プロセスブラックリスト"><strong>設定 → ホットキー</strong></a> で、操作中のアプリが「プロセスブラックリスト」に含まれていないか確認してください。リスト内のアプリがアクティブな場合、Lertaro はホットキーを意図的にスルーします。</li><li><strong>全画面アプリでの自動バイパス</strong>：フルスクリーンのゲームや動画プレイヤーがアクティブな場合、操作を妨げないようホットキーは既定で無効化されます。全画面時も呼び出したい場合は、<strong>設定 → ホットキー</strong> で <strong>全画面アプリフォーカス時も応答する</strong> を有効にしてください。</li></ul><h2 id="_2-検索結果が更新されない・古い" tabindex="-1">2. 検索結果が更新されない・古い <a class="header-anchor" href="#_2-検索結果が更新されない・古い" aria-label="Permalink to &quot;2. 検索結果が更新されない・古い&quot;">​</a></h2><ul><li><strong>NTFS / ReFS ドライブ</strong>：ファイルシステムの USN 変更ジャーナルを読み取ることで、遅延ゼロのミリ秒単位でリアルタイム更新されます。</li><li><strong>FAT32 / exFAT ドライブ</strong>：ファイルシステムの変更イベントにより継続的に監視されます。</li><li><strong>手動でのインデックス再構築</strong>：PC の強制終了等でインデックスの整合性が崩れた場合は、<a href="./settings/index-drives.html"><strong>設定 → インデックス → ローカルドライブ</strong></a> で該当ドライブの <strong>インデックス再構築</strong> を実行してください。</li></ul><h2 id="_3-ネットワークドライブが自動更新されない" tabindex="-1">3. ネットワークドライブが自動更新されない <a class="header-anchor" href="#_3-ネットワークドライブが自動更新されない" aria-label="Permalink to &quot;3. ネットワークドライブが自動更新されない&quot;">​</a></h2><ul><li><strong>定期スキャンの仕組み</strong>：ネットワーク共有（SMB / NAS）にはローカルの変更ジャーナルが存在しないため、定期ポーリングに依存します。</li><li><strong>更新モードの確認</strong>：<a href="./settings/index-drives.html#ネットワークドライブ"><strong>設定 → インデックス → ネットワークドライブ</strong></a> で、更新モードが「手動」になっていないか確認してください。手動の場合は定期更新に切り替えるか、「インデックス再構築」をクリックしてください。</li><li><strong>シンボリックリンク循環保護</strong>：NAS 上の循環シンボリックリンクによる無限ループを防ぐため、ループ検知機能が自動で重複パスをスキップします。</li></ul><h2 id="_4-特定のファイルやフォルダーが見つからない" tabindex="-1">4. 特定のファイルやフォルダーが見つからない <a class="header-anchor" href="#_4-特定のファイルやフォルダーが見つからない" aria-label="Permalink to &quot;4. 特定のファイルやフォルダーが見つからない&quot;">​</a></h2><ul><li><strong>除外ルールの確認</strong>：<a href="./settings/index-drives.html#除外ルール"><strong>設定 → インデックス → 除外ルール</strong></a> を確認し、完全パス、ワイルドカード、正規表現によって誤って除外されていないか確認してください。</li><li><strong>ドライブの有効化確認</strong>：<a href="./settings/index-drives.html"><strong>設定 → インデックス → ローカルドライブ</strong></a> で、対象のドライブが有効になっていることを確認してください。</li></ul><h2 id="_5-インラインウィンドウで日本語-ime-の候補窓が出ない" tabindex="-1">5. インラインウィンドウで日本語 IME の候補窓が出ない <a class="header-anchor" href="#_5-インラインウィンドウで日本語-ime-の候補窓が出ない" aria-label="Permalink to &quot;5. インラインウィンドウで日本語 IME の候補窓が出ない&quot;">​</a></h2><ul><li><strong>非フォーカス設計の特性</strong>：<a href="./getting-started.html#3-3-つのウィンドウ形態">インラインウィンドウ</a> は、閉じた後に元のアプリへ瞬時に操作を戻すため、キーボードフォーカスを奪わない設計になっています。IME の候補窓は Windows の正規フォーカスを必要とするため、インラインでは表示されない場合があります。</li><li><strong>推奨する対処法</strong>： <ol><li><strong>クイックウィンドウを利用</strong>：<code>Ctrl</code> 2 回連打で開くクイックウィンドウは完全なフォーカスを持つため、すべての IME が正常に動作します。</li></ol></li></ul><h2 id="_6-ログの確認と-issue-の報告" tabindex="-1">6. ログの確認と Issue の報告 <a class="header-anchor" href="#_6-ログの確認と-issue-の報告" aria-label="Permalink to &quot;6. ログの確認と Issue の報告&quot;">​</a></h2><p>上記の手順で解決しない場合は、<a href="./settings/service-status.html"><strong>設定 → サービス状態</strong></a> でログを確認してください。</p><ul><li><strong>Service ログ</strong>：インデックス作成、USN ジャーナル、ネットワークスキャン、IPC 通信のログ。</li><li><strong>App ログ</strong>：UI 描画、プラグイン、ホットキー、設定変更のログ。</li><li><strong>Hook ログ</strong>：グローバルキーフックおよびマウス操作イベントのログ。</li></ul><p>検索ボックスや重要度フィルター（Info / Warn / Error）を活用してエラーを特定し、GitHub Issue を報告する際にログを添付してください。</p>',16)])])}const _=r(a,[["render",n]]);export{c as __pageData,_ as default};
